INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Kundenkommunikation ein wesentlicher Bestandteil des Projektmanagements?', 2, '[{"text": "Ja", "correct": true, "because": "Sichert Abstimmung"}, {"text": "Nein", "correct": false, "because": "Sie ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt die Kundenkommunikation?', 3, '[{"text": "Kundenzufriedenheit und Klarheit schaffen", "correct": true, "because": "Fördert Verständnis"}, {"text": "Projekt direkt umsetzen", "correct": false, "because": "Teamaufgabe"}, {"text": "Kosten allein festlegen", "correct": false, "because": "Auftraggeberaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kundenkommunikation klärt Anforderungen. b) Sie ist nur im Abschluss wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, durchgehend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Kundenkommunikation?', 4, '[{"text": "Regelmäßige Updates", "correct": true, "because": "Informieren Kunden"}, {"text": "Unklare Antworten", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Anforderungsabstimmung", "correct": true, "because": "Klärung der Ziele"}, {"text": "Feedback einholen", "correct": true, "because": "Sichert Zufriedenheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Kundenkommunikation erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Abstimmung fehlt"}, {"text": "Ja", "correct": false, "because": "Unzufriedenheit droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Kundenkommunikation in der Initiierung?', 3, '[{"text": "Anforderungen und Erwartungen klären", "correct": true, "because": "Legt Grundlage"}, {"text": "Technische Umsetzung", "correct": false, "because": "Teamaufgabe"}, {"text": "Kosten direkt kalkulieren", "correct": false, "because": "Controlling-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Kundenkommunikation nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen sie"}, {"text": "Ja", "correct": false, "because": "Universelle Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Verantwortung hat der Projektleiter in der Kundenkommunikation?', 3, '[{"text": "Kunden über Fortschritt informieren", "correct": true, "because": "Fördert Vertrauen"}, {"text": "Projekt allein finanzieren", "correct": false, "because": "Auftraggeberaufgabe"}, {"text": "Technische Details umsetzen", "correct": false, "because": "Teamaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kundenkommunikation vermeidet Missverständnisse. b) Sie ist nur schriftlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch mündlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Kundenkommunikation?', 3, '[{"text": "Unklare Erwartungen", "correct": true, "because": "Fehlende Abstimmung"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kundenzufriedenheit steigt", "correct": false, "because": "Unzufriedenheit droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Kundenkommunikation ohne Projektleiter erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "Team kann kommunizieren"}, {"text": "Nein", "correct": false, "because": "Flexibilität möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt Kundenkommunikation?', 3, '[{"text": "Statusbericht an Kunden senden", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas mitteilen", "correct": false, "because": "Zu vage"}, {"text": "Team soll reden", "correct": false, "because": "Keine klare Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Kundenkommunikation nur für den Projektstart wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Über alle Phasen relevant"}, {"text": "Ja", "correct": false, "because": "Projektweite Bedeutung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine effektive Kundenkommunikation?', 4, '[{"text": "Klarheit", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Unklare Aussagen", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Regelmäßigkeit", "correct": true, "because": "Hält Kunden informiert"}, {"text": "Transparenz", "correct": true, "because": "Fördert Vertrauen"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss Kundenkommunikation dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis und Klarheit"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt Kundenkommunikation?', 3, '[{"text": "E-Mail für Updates", "correct": true, "because": "Fördert Austausch"}, {"text": "Keine Kommunikation", "correct": false, "because": "Fehlt Kontakt"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Kundenkommunikation ohne Feedback erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Rückmeldung wichtig"}, {"text": "Ja", "correct": false, "because": "Einseitig unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Kundenkommunikation?', 3, '[{"text": "Unklare Anforderungen", "correct": true, "because": "Verhindern Verständnis"}, {"text": "Regelmäßige Updates", "correct": false, "because": "Fördern Klarheit"}, {"text": "Gute Dokumentation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kundenkommunikation steigert Akzeptanz. b) Sie ist nur mündlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch schriftlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der appeaseKundenkommunikation?', 3, '[{"text": "Vertrauen und Zufriedenheit fördern", "correct": true, "because": "Sichert Erfolg"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Abstimmung", "correct": false, "because": "Fördert Verständnis"}]');
